const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={customers:[{name:'JDLN Internal',type:'Internal infrastructure',contact:'Operations',status:'Healthy'},{name:'School · Demo',type:'Education',contact:'IT coordinator',status:'Attention'},{name:'Decor · Demo',type:'Business',contact:'Office administrator',status:'Healthy'}],assets:[{name:'PVE-01',type:'Proxmox',customer:'JDLN Internal',address:'192.168.5.2',status:'Healthy',cpu:28,ram:64},{name:'TrueNAS',type:'Storage',customer:'JDLN Internal',address:'truenas.local',status:'Healthy',cpu:12,ram:42},{name:'AdGuard Home',type:'DNS',customer:'JDLN Internal',address:'192.168.5.10',status:'Healthy',cpu:4,ram:18},{name:'Pangolin',type:'VPN / Proxy',customer:'JDLN Internal',address:'pangolin.jdln.co.za',status:'Warning',cpu:17,ram:36},{name:'MikroTik Gateway',type:'Router',customer:'JDLN Internal',address:'gateway.local',status:'Healthy',cpu:9,ram:24},{name:'UniFi Controller',type:'Network',customer:'School · Demo',address:'unifi.jdln.co.za',status:'Healthy',cpu:8,ram:31}],alerts:[{id:1,title:'Backup job needs attention',source:'PVE-01 · JDLN Internal',severity:'critical',detail:'Demo alert: nightly backup did not complete. Review storage availability and backup logs.',ack:false},{id:2,title:'Relay DNS lookup timeout',source:'Pangolin · JDLN Internal',severity:'warning',detail:'Demo alert: relay endpoint resolution timed out. Check the client DNS route and AdGuard reachability.',ack:false},{id:3,title:'Access point offline',source:'UniFi · School Demo',severity:'warning',detail:'Demo alert: classroom access point is unreachable. Check PoE and switch port status.',ack:false}],tasks:[{title:'Review nightly backup',agent:'JARVIS',status:'Queued'},{title:'Prepare Pangolin DNS diagnostic',agent:'Doctor Strange',status:'In progress'},{title:'Review network device inventory',agent:'JARVIS',status:'Completed'}],integrations:{},activity:[]};let state;try{state=JSON.parse(localStorage.getItem('jdln-mc-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}let selectedAgent='JARVIS';const chats={'JARVIS':[],'Doctor Strange':[]};
const views=[['overview','◫','Overview'],['customers','◇','Customers'],['infrastructure','▤','Infrastructure'],['network','⌘','Network'],['alerts','△','Alerts'],['agents','✧','AI agents'],['tasks','☷','Tasks'],['integrations','⚙','Integrations']];function legacySave(message){localStorage.setItem('jdln-mc-v1',JSON.stringify(state));if(message)toast(message)}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}function log(s){state.activity.unshift({text:s,time:new Date().toLocaleTimeString('en-ZA',{timeZone:'Africa/Johannesburg',hour:'2-digit',minute:'2-digit'})});state.activity=state.activity.slice(0,12)}function tag(s){return `<span class="tag ${/Warning|Attention|Queued|Pending|pending|Stale|stale/.test(s)?'warning':/Critical|failed|HTTP|blocked|rejected|Invalid|Disconnected/.test(s)?'critical':/Disconnected|Configured|Acknowledged|Not tested|Unmonitored/.test(s)?'neutral':''}">${esc(s)}</span>`}function head(title,desc,buttons=''){return `<div class="page-head"><div><div class="eyebrow">OPERATIONS / ${esc(title.toUpperCase())}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${buttons}</div></div>`}function button(label,action,primary=false){return `<button class="btn ${primary?'primary':''}" ${action}>${label}</button>`}function panel(title,body,link='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<div class="sub">${sub}</div>`:''}</div>${link}</div>${body}</section>`}function go(id){location.hash=id}function updateNav(view){$('#nav').innerHTML=views.map(([id,icon,label])=>`<a href="#${id}" class="${id===view?'active':''}" title="${label}" ${id===view?'aria-current="page"':''}><span class="symbol">${icon}</span><span class="nav-text">${label}</span>${id==='alerts'?`<span class="count">${operationAlerts().filter(a=>!a.ack).length}</span>`:''}</a>`).join('');$('#crumb').textContent=views.find(x=>x[0]===view)[2];$('#alert-badge').textContent=operationAlerts().filter(a=>!a.ack).length}function assetsTable(assets,full=false){const all=inventory();return `<div class="table-wrap"><table><thead><tr><th>DEVICE</th><th>STATUS</th><th>${full?'CUSTOMER':'SOURCE'}</th><th>${full?'ADDRESS / MODEL':'CLIENTS'}</th>${full?'<th></th>':''}</tr></thead><tbody>${assets.map(a=>`<tr><td><div class="device-name"><span class="device-icon">▤</span><div>${esc(a.name)}<small>${esc(a.type)}${a.site?' · '+esc(a.site):''}</small></div></div></td><td>${tag(a.status)}${a.live?`<small class="${a.stale?'amber':'green'}">${a.stale?'Cached · stale':'Current snapshot'}</small>`:''}</td><td>${esc(full?a.customer:a.source||'Registered inventory')}</td><td>${esc(full?a.address||a.model||'—':a.num_sta??'—')}</td>${full?`<td><button class="text-link" onclick="assetDetail(${all.findIndex(x=>a.liveKey?x.liveKey===a.liveKey:x===a)})">Details ↗</button> ${a.live?'<small>Integration managed</small>':`<button class="text-link red" onclick="deleteAsset(${all.findIndex(x=>x===a)})">Delete</button>`}</td>`:''}</tr>`).join('')||'<tr><td colspan="5">No matching devices.</td></tr>'}</tbody></table></div>`}function alertsRows(list,full=false){return list.map(a=>`<div class="alert-row"><div class="alert-symbol ${a.severity}">!</div><div><h3>${esc(a.title)}</h3><p>${esc(a.source)}</p><small>${a.ack?'Acknowledged':'Needs review'} · ${a.live?'Integration telemetry':'Saved workspace alert'}</small>${full?`<p style="margin-top:9px;max-width:700px">${esc(a.detail)}</p>`:''}</div><button class="text-link" onclick="${full?(a.live?`go('integrations')`:`ack(${a.id})`):`go('alerts')`}">${full?(a.live?'View integration ↗':a.ack?'Reopen':'Acknowledge'):'↗'}</button></div>`).join('')||'<div class="empty">No open alerts. All caught up.</div>'}
function overview(){const open=operationAlerts().filter(a=>!a.ack);return head('Your operations, at a glance.','A clear view of your infrastructure, customers and AI team.',button('↓ Export report','onclick="exportData()"')+button('+ New task','onclick="newTask()"',true))+`<div class="stats">${[['Managed customers',state.customers.length,'Customer workspaces','◇',''],['Infrastructure',inventory().length,'Registered assets and integration devices','▤',''],['Open alerts',open.length,open.filter(a=>a.severity==='critical').length+' critical · review required','△','amber'],['AI agents','2','Awaiting live API connection','✧','']].map(([label,value,hint,icon,color])=>`<div class="stat"><div class="label">${label}</div><span class="stat-icon">${icon}</span><div class="value ${color}">${value}${label==='AI agents'?'<span>configured</span>':''}</div><div class="hint">${hint}</div></div>`).join('')}</div><div class="grid"><div>${vault.length?integrationPulse():panel('Infrastructure pulse',`<div class="chart-wrap"><div class="chart-meta"><div><strong>99.8<small>% sample uptime</small></strong></div><div class="legend"><span class="green">● CPU usage</span><span style="color:var(--blue)">● Memory</span></div></div><svg class="chart" viewBox="0 0 620 150" preserveAspectRatio="none" role="img" aria-label="Illustrative CPU and memory trend, demo data"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7de2b1" stop-opacity=".16"/><stop offset="1" stop-color="#7de2b1" stop-opacity="0"/></linearGradient></defs><g stroke="#25303c" stroke-dasharray="3 5"><path d="M0 25H620M0 65H620M0 105H620M0 145H620"/></g><path d="M0 110L24 109L46 90L68 99L90 95L114 115L140 111L161 83L187 94L214 104L240 75L263 95L290 91L314 112L339 102L365 105L390 80L417 95L442 102L465 87L493 92L519 70L546 84L572 76L597 87L620 82V150H0Z" fill="url(#fade)"/><path d="M0 110L24 109L46 90L68 99L90 95L114 115L140 111L161 83L187 94L214 104L240 75L263 95L290 91L314 112L339 102L365 105L390 80L417 95L442 102L465 87L493 92L519 70L546 84L572 76L597 87L620 82" fill="none" stroke="#7de2b1" stroke-width="2"/><path d="M0 65L30 64L60 69L90 59L120 61L150 59L180 63L210 60L240 61L270 50L300 53L330 52L360 59L390 53L420 51L450 48L480 50L510 46L540 49L570 44L600 47L620 45" fill="none" stroke="#81b6ff" stroke-width="2"/></svg><div class="chart-labels"><span>00:00</span><span>04:00</span><span>08:00</span><span>12:00</span><span>16:00</span><span>20:00</span></div></div><div class="health-strip"><span>Sample CPU <b>28%</b></span><span>Sample memory <b>64%</b></span><span class="green">● Demo metrics</span></div>`,tag('Illustrative · 24h'))}${panel('Infrastructure inventory',assetsTable(inventory().slice(0,6)),`<button class="text-link" onclick="go('infrastructure')">All devices ↗</button>`, 'Inventory and connected integrations')}${panel('Recent activity',`<div class="activity">${state.activity.length?state.activity.map(a=>`<div class="activity-row"><span class="dot"></span><div><p>${esc(a.text)}</p><small>${esc(a.time)} SAST · Browser activity</small></div></div>`).join(''):'<div class="activity-row"><span class="dot"></span><div><p>Mission Control workspace ready</p><small>Add customers, register assets or queue a task to get started.</small></div></div>'}</div>`)}</div><div>${panel('Your AI team',agentCard('JARVIS','Operations & orchestration','Daily health review and incident triage'),tag('1 agent'))}${panel('Needs your attention',alertsRows(open.slice(0,3)),`<button class="text-link" onclick="go('alerts')">View all ↗</button>`)}${panel('Workspace readiness',`<div style="padding:21px"><p style="font-size:11px">Your command centre is ready. The secure backend is ready. Add endpoints and credentials in Integrations to test your services. UniFi telemetry updates from the backend every 60 seconds, including while the dashboard is closed. Pangolin telemetry also refreshes every 60 seconds. MikroTik and AdGuard Home also refresh every 60 seconds. Each integration uses a dedicated read-only connector; agent dispatch requires a service adapter.</p><div style="margin-top:18px">${button('Configure integrations ↗','onclick="go(\'integrations\')"')}</div></div>`)}</div></div>`}
function agentCard(name,role,task){return `<div class="agent-card"><div class="agent-top"><div class="agent-icon ${name==='JARVIS'?'':'purple'}">${name==='JARVIS'?'J':'S'}</div><div><h3>${name}</h3><small>${role}</small></div>${agentConnection(name)}</div><div class="agent-task"><span>↳</span>${task}</div><div class="agent-foot"><span>HERMES AGENT</span><button class="btn tiny" onclick="openAgent('${name}')">Open workspace ↗</button></div></div>`}
function customers(){return head('Customer workspaces','Keep every customer and their infrastructure in view.',button('+ Add customer','onclick="newCustomer()"',true))+`<div class="customer-grid">${state.customers.map((c,i)=>`<section class="panel customer-card"><span class="device-icon">◇</span><h3>${esc(c.name)}</h3><p>${esc(c.type)}<br>${esc(c.contact)}</p><div class="card-bottom">${tag(customerStatus(c))}<span>${vault.filter(x=>x.customer===c.name).length} integrations</span><button class="text-link" onclick="customerDetail(${i})">${inventory().filter(a=>a.customer===c.name).length} assets ↗</button></div><div class="actions" style="margin-top:16px">${button('Edit','onclick="editCustomer('+i+')"')}${button('Delete','onclick="deleteCustomer('+i+')"')}</div></section>`).join('')}</div>`}
function infrastructure(){return head('Infrastructure inventory','Registered assets and devices discovered by your integrations.',button('+ Register asset','onclick="newAsset()"',true))+`<div class="notice">Integration devices use the latest backend snapshot. Stale data retains its last reported state. Manually registered assets keep their saved inventory status.</div><div class="toolbar"><input id="asset-search" aria-label="Search devices" placeholder="Search devices, addresses or customers…" oninput="filterAssets()"><select id="asset-status" aria-label="Filter status" onchange="filterAssets()"><option>All statuses</option><option>Healthy</option><option>Warning</option><option>Unmonitored</option><option>Connected</option><option>Stopped</option><option>Critical</option><option>Disconnected</option><option>Pending / other</option><option>Discovery / pending</option><option>Unknown</option><option>Stale</option></select></div><section class="panel" id="asset-table">${assetsTable(inventory(),true)}</section>`}function filterAssets(){const q=$('#asset-search').value.toLowerCase(),s=$('#asset-status').value;$('#asset-table').innerHTML=assetsTable(inventory().filter(a=>Object.values(a).some(v=>String(v).toLowerCase().includes(q))&&(s==='All statuses'||a.status===s||(s==='Stale'&&a.stale))),true)}
function network(){return head('Network operations','Network devices, clients and subsystem health from your integrations.')+integrationPulse()+vault.filter(i=>telemetryConnector(i)).map(i=>classicPanel(i.id,false)).join('')+panel('Network device inventory',assetsTable(inventory().filter(a=>a.live||['Router','Network','DNS','VPN / Proxy'].includes(a.type)),true))}
function alerts(){return head('Alert centre','Review incidents and acknowledge items that need attention.')+`<div class="toolbar"><select id="alert-filter" aria-label="Filter alerts" onchange="renderAlerts()"><option>Open alerts</option><option>All alerts</option><option>Acknowledged</option></select></div><section class="panel" id="alerts-list">${alertsRows(operationAlerts().filter(a=>!a.ack),true)}</section>`}function renderAlerts(){let v=$('#alert-filter').value;$('#alerts-list').innerHTML=alertsRows(operationAlerts().filter(a=>v==='All alerts'||(v==='Open alerts'?!a.ack:a.ack)),true)}function ack(id){let a=state.alerts.find(x=>x.id===id);a.ack=!a.ack;log(`${a.ack?'Acknowledged':'Reopened'}: ${a.title}`);save('Alert updated');render()}
function agents(){return head('AI agent workspace','Two specialised agents. One operations interface.')+`<div class="notice">Demo conversation mode. Messages stay in this page session; no messages are sent to Hermes. Configure and test API credentials in Integrations. Live conversation needs a Hermes dispatch adapter.</div><div class="chat-layout"><div class="chat-agents">${['JARVIS','Doctor Strange'].map(n=>`<div class="agent-select ${n===selectedAgent?'selected':''}"><button class="text-link" style="text-align:left" onclick="openAgent('${n}')"><h2>${n}</h2><small>${n==='JARVIS'?'Operations & orchestration':'Engineering & diagnostics'}</small><div style="margin-top:15px">${agentConnection(n)}</div></button></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${selectedAgent}</h2>${tag('Demo conversation')}</div><div class="chat-log" id="chat-log">${chats[selectedAgent].length?chats[selectedAgent].map(m=>`<div class="bubble ${m.role}">${esc(m.text)}</div>`).join(''):`<div class="bubble">${selectedAgent==='JARVIS'?'Welcome to Mission Control. I’m your operations agent.':'Doctor Strange workspace ready. Let’s organise your next diagnostic or engineering task.'}\n\nThis is a demo workspace. Connect your Hermes API for live responses.</div>`}</div><form class="chat-form" onsubmit="sendChat(event)"><input id="chat-input" placeholder="Try: review open alerts…" aria-label="Message" required maxlength="2000"><button class="btn primary">Send demo message ↗</button></form></section></div><div class="quick-prompts">${['Review open alerts','Summarise infrastructure','Plan a backup check'].map(p=>`<button class="btn" onclick="promptChat('${p}')">${p}</button>`).join('')}${button('+ Queue an agent task','onclick="newTask()"')}</div>`}function openAgent(n){selectedAgent=n;if(location.hash==='#agents')render();else go('agents')}function promptChat(p){$('#chat-input').value=p;sendChat({preventDefault(){}})}function sendChat(e){e.preventDefault();let t=$('#chat-input').value.trim();if(!t)return;chats[selectedAgent].push({role:'user',text:t});let reply=/alert/i.test(t)?`Demo summary: ${operationAlerts().filter(a=>!a.ack).length} open alerts.\n${state.alerts.filter(a=>!a.ack).map(a=>'• '+a.title).join('\n')}\n\nReview these in the Alert centre. Live investigation requires a connected Hermes API.`:/infrastructure|server/i.test(t)?`Your inventory has ${state.assets.length} assets across ${state.customers.length} customer workspaces. Sample telemetry is displayed on Overview. Live infrastructure analysis requires a monitoring connection.`:'Demo response: turn this request into an agent task using “Queue an agent task”. The task will be saved on the server for planning. A Hermes dispatch adapter is needed to send tasks and receive real results.';chats[selectedAgent].push({role:'',text:reply});render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight}
function tasks(){return head('Task board','Plan work for your AI team and track progress.',button('+ New task','onclick="newTask()"',true))+`<div class="notice">Tasks are a server-saved planning board. Changing status does not dispatch a job to an agent.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>TASK</th><th>ASSIGNED AGENT</th><th>STATUS</th><th></th></tr></thead><tbody>${state.tasks.map((t,i)=>`<tr><td>${esc(t.title)}</td><td>${esc(t.agent)}</td><td><select aria-label="Task status for ${esc(t.title)}" onchange="taskStatus(${i},this.value)">${['Queued','In progress','Completed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="text-link" onclick="removeTask(${i})">Remove</button></td></tr>`).join('')||'<tr><td colspan="4">No tasks yet.</td></tr>'}</tbody></table></div></section>`}function taskStatus(i,s){state.tasks[i].status=s;log(`${state.tasks[i].title}: ${s}`);save('Task status saved')}function removeTask(i){showModal(`<h2>Remove task?</h2><p>${esc(state.tasks[i].title)}</p><div class="form-actions">${button('Cancel','onclick="closeModal()"')}${button('Remove','onclick="confirmRemoveTask('+i+')"',true)}</div>`)}function confirmRemoveTask(i){state.tasks.splice(i,1);save('Task removed');closeModal();render()}
const services=[['JARVIS','Hermes operations API'],['Doctor Strange','Hermes coding API'],['Proxmox','Hosts, containers & backups'],['MikroTik','Routing & network telemetry'],['AdGuard Home','DNS health & filtering'],['Pangolin','Remote access & proxy'],['Wazuh','Security monitoring'],['UniFi','Switches & access points'],['TrueNAS','Storage & backup capacity']];function legacyIntegrations(){return head('Integration settings','Prepare the connections that power your command centre.')+`<div class="notice">Endpoint references only. Saving an address does not connect or test a service. Live integration needs a secure backend or private-service bridge with server-side credentials. Do not enter passwords or API tokens here.</div><div class="integration-grid">${services.map(([n,d])=>`<section class="panel integration"><div style="display:flex;justify-content:space-between"><span class="device-icon">${n.includes('Strange')||n==='JARVIS'?'✧':'⌘'}</span>${tag(state.integrations[n]?'Configured reference':'Disconnected')}</div><h3>${n}</h3><p>${d}</p><p style="margin-top:12px;overflow-wrap:anywhere">${esc(state.integrations[n]||'No endpoint reference saved')}</p><div class="card-bottom"><button class="btn tiny" onclick="configure('${n}')">${state.integrations[n]?'Edit reference':'Configure reference'} ↗</button></div></section>`).join('')}</div>`}
function showModal(html){detailModal=null;$('#modal-content').innerHTML=html;$('#modal').showModal()}function closeModal(){detailModal=null;$('#modal').close()}function formModal(title,fields,submit){showModal(`<h2>${title}</h2><form id="entry-form">${fields}<div class="form-actions">${button('Cancel','type="button" onclick="closeModal()"')}<button class="btn primary">Save</button></div></form>`);$('#entry-form').onsubmit=e=>{e.preventDefault();submit(new FormData(e.target));closeModal();render()}}const field=(label,name,value='',required=true)=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" ${required?'required':''} maxlength="200">`;function legacyNewCustomer(){formModal('Add customer',field('Customer name','name')+field('Business / category','type')+field('Contact role or name','contact'),f=>{state.customers.push({name:f.get('name').trim(),type:f.get('type').trim(),contact:f.get('contact').trim(),status:'Healthy'});log('Added customer: '+f.get('name'));save('Customer added')})}function newAsset(){formModal('Register asset',field('Device name','name')+field('Type / platform','type')+`<label for="f-customer">Customer</label><select id="f-customer" name="customer">${state.customers.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select>`+field('IP address or hostname','address'),f=>{state.assets.push({name:f.get('name').trim(),type:f.get('type').trim(),customer:f.get('customer'),address:f.get('address').trim(),status:'Unmonitored',cpu:0,ram:0});log('Registered asset: '+f.get('name'));save('Asset registered')})}function newTask(){formModal('Queue an agent task',field('Task description','title')+`<label for="f-agent">Assign to</label><select id="f-agent" name="agent"><option ${selectedAgent==='JARVIS'?'selected':''}>JARVIS</option><option ${selectedAgent==='Doctor Strange'?'selected':''}>Doctor Strange</option></select><p style="font-size:11px;margin-top:15px">Saved on the server for planning. Not sent to Hermes.</p>`,f=>{state.tasks.push({title:f.get('title').trim(),agent:f.get('agent'),status:'Queued'});log('Queued task: '+f.get('title'));save('Task queued')})}function assetDetail(i){const a=inventory()[i];if(!a)return;showModal(`<h2>${esc(a.name)}</h2>${tag(a.status)}<p style="margin-top:18px">Platform: ${esc(a.type)}<br>Customer: ${esc(a.customer)}<br>${a.live&&a.model?'Model: '+esc(a.model):'Address: '+esc(a.address||'—')}${a.site?'<br>Site: '+esc(a.site):''}${a.live?'<br>Integration: '+esc(a.source)+(a.recordType?'<br>Adoption: '+esc(a.recordType):'')+(a.uptime!==undefined?'<br>Uptime: '+esc(a.uptime)+(a.type.startsWith('MikroTik')?'':' seconds'):'')+(a.version?'<br>Version: '+esc(a.version):'')+(a.dnsRunning!==undefined?'<br>DNS service: '+esc(a.dnsRunning===true?'Running':a.dnsRunning===false?'Stopped':'Unknown')+'<br>Protection: '+esc(a.protectionEnabled===true?'Enabled':a.protectionEnabled===false?'Disabled':'Unknown'):''):''}</p><div class="notice" style="margin-top:20px">${a.live?'Integration-managed asset. Delete its integration to remove it. '+esc((a.stale?'Cached data stale. ':'Last reported state. ')+(a.lastSuccess?'Last successful update: '+new Date(a.lastSuccess).toLocaleString('en-ZA'):'No successful update yet')):a.status==='Unmonitored'?'This registered asset has no live monitoring.':'Health and utilisation are demo values. Connect monitoring to see real device data.'}</div><div class="form-actions">${button('Close','onclick="closeModal()"')}${button('Plan a task','onclick="closeModal();newTask()"',true)}${a.live?button('Manage integration','onclick="closeModal();go(\'integrations\')"'):button('Delete asset','onclick="deleteAsset('+i+')"')}</div>`);detailModal={type:'asset',key:a.liveKey||a.name}}function customerDetail(i){let c=state.customers[i];showModal(`<h2>${esc(c.name)}</h2><p>${esc(c.type)} · ${esc(c.contact)}</p><div style="margin-top:20px">${inventory().filter(a=>a.customer===c.name).map(a=>`<p style="margin:10px 0">${esc(a.name)} ${tag(a.status)}</p>`).join('')||'<p>No assets registered yet.</p>'}${customerIntegrations(c.name)}</div><div class="form-actions">${button('Close','onclick="closeModal()"')}${button('Register asset','onclick="closeModal();newAsset()"',true)}${button('Edit customer','onclick="editCustomer('+i+')"')}${button('Delete customer','onclick="deleteCustomer('+i+')"')}</div>`);detailModal={type:'customer',name:c.name}}function legacyConfigure(n){formModal(n+' endpoint reference',`<p style="font-size:11px">Store an address for future setup. Credentials must be handled by a secure backend.</p>`+field('HTTP(S) endpoint URL','endpoint',state.integrations[n]||'',false),f=>{const value=f.get('endpoint').trim();if(value){try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error();state.integrations[n]=u.href}catch{toast('Use an HTTP(S) URL without credentials, query parameters or fragments.');return}}else delete state.integrations[n];log('Updated endpoint reference: '+n);save('Reference saved · service remains disconnected')});$('#f-endpoint').type='url'}function exportData(){const blob=new Blob([JSON.stringify({...state,integrations:vault,exportedAt:new Date().toISOString(),environment:'operations',liveConnected:vault.some(i=>i.status==='Connected'),integrationData:classicData},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='jdln-operations-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Operations report exported')}
function render(){const v=location.hash.slice(1);const view=views.some(x=>x[0]===v)?v:'overview';updateNav(view);$('#main').innerHTML=({overview,customers,infrastructure,network,alerts,agents,tasks,integrations}[view])()}window.addEventListener('hashchange',render);$('#notifications').onclick=()=>go('alerts');$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});function clock(){$('#clock').textContent=new Date().toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' SAST'}clock();setInterval(clock,30000);bootBackend();
