let classicData={},classicOpened=null,pollRunning=false,workspaceEpoch=0,workspaceMutation=false,workspaceDirty=false,saveVersion=0,detailModal=null;let vault=[],auditEvents=[],backendReady=false,syncChain=Promise.resolve();
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await r.json()}catch{throw Error('Backend unavailable. Reload the page and try again.')}if(r.status===401){location.href='/login';throw Error('Sign in required.')}if(!r.ok)throw Error(data.error||'Request failed.');return data}
function workspaceData(){return Object.fromEntries(['customers','assets','alerts','tasks','activity'].map(k=>[k,state[k]]))}
function save(message){if(!backendReady){toast('Workspace is not connected to the backend. Reload to reconnect.');return}workspaceEpoch++;workspaceDirty=true;const version=++saveVersion;const snapshot=structuredClone(workspaceData());syncChain=syncChain.catch(()=>{}).then(()=>api('workspace','PUT',snapshot)).then(()=>{if(version===saveVersion)workspaceDirty=false;if(message)toast(message+' · saved securely')}).catch(e=>toast('Server save failed: '+e.message+' Export your records before leaving.'))}
async function refreshVault(){const d=await api('integrations');vault=d.integrations;const a=await api('audit');auditEvents=a.events;await loadClassicData()}
async function bootBackend(){document.querySelector('.environment').innerHTML='<i></i> Secure workspace<span>Connecting to backend…</span>';$('#main').innerHTML='<div class="empty">Loading your secure workspace…</div>';try{const [w,v,a]=await Promise.all([api('workspace'),api('integrations'),api('audit')]);if(w.data){state={...structuredClone(seed),...w.data,integrations:{}}}else{state=structuredClone(seed);state.integrations={};await api('workspace','PUT',workspaceData())}vault=v.integrations;auditEvents=a.events;backendReady=true;await loadClassicData();document.querySelector('.environment').innerHTML='<i></i> Secure workspace<span>'+vault.filter(x=>x.status==='Connected').length+' integrations passed connection tests</span>';document.querySelector('footer span:nth-child(2)').textContent='Server-saved records · Integration polling every 60s';render();pollIntegrations()}catch(e){$('#main').innerHTML='<div class="notice">'+esc(e.message)+'</div><button class="btn primary" onclick="bootBackend()">Retry connection</button>';document.querySelector('.environment').innerHTML='Backend unavailable<span>Records cannot be saved right now</span>'}}
function integrations(){return head('Secure integrations','Configure endpoints, protect credentials and test connectivity.',button('+ Add integration','onclick="configure()"',true))+`<div class="notice">Credentials are encrypted on the server and never returned to this browser. Choose a dedicated connector for your service. For Pangolin-protected HTTP services, add a resource access token separately from the service credentials. UniFi Classic, Pangolin, MikroTik, AdGuard Home and Pulse read their supported API endpoints; agent dispatch remains disabled.</div><div class="integration-grid">${vault.map(i=>`<section class="panel integration"><div style="display:flex;justify-content:space-between"><span class="device-icon">⌘</span>${tag(i.status)}</div><h3>${esc(i.name)}</h3><p>${esc(i.customer||'Unassigned')} · ${telemetryConnector(i)?(i.connector==='pulse'?'Pulse · Proxmox PVE':i.connector==='adguard'?'AdGuard Home':i.connector==='mikrotik-api'?'MikroTik Native API':i.connector==='pangolin'?'Pangolin Network':'UniFi Classic Network'):'Removed connector'}</p><p style="margin-top:12px;overflow-wrap:anywhere">${esc(i.target||i.endpoint)}</p><small>${i.auth==='none'?'No service authentication':esc(i.auth)+' · credential saved'}${i.mode==='bridge'?' · bridge token saved':''}${i.proxyAuth?' · Pangolin token saved':''}</small>${telemetryConnector(i)?classicSummary(i.id):removedConnectorNotice(i)}<small>${i.checkedAt?'Last checked '+esc(new Date(i.checkedAt).toLocaleString('en-ZA'))+' · '+i.latency+' ms':'Not tested yet'}</small><div class="card-bottom" style="gap:8px;flex-wrap:wrap">${telemetryConnector(i)?`<button class="btn tiny" onclick="testIntegration('${i.id}',this)">Test connection</button>`:''}${telemetryConnector(i)?`<button class="text-link" onclick="viewClassic('${i.id}')">View data</button>`:''}<button class="text-link" onclick="configure('${i.id}')">Edit</button><button class="text-link red" onclick="deleteIntegration('${i.id}')">Remove</button></div></section>`).join('')||'<section class="panel integration"><h3>Connect your first service</h3><p>Add UniFi Classic Network, Pangolin Network, MikroTik Native API, AdGuard Home or Pulse.</p><div style="margin-top:20px">'+button('+ Add integration','onclick="configure()"',true)+'</div></section>'}</div>${classicOpened?classicPanel(classicOpened):''}${panel('Integration activity',`<div class="activity">${auditEvents.map(a=>`<div class="activity-row"><span class="dot"></span><div><p>${esc(a.action)} · ${esc(a.name)}</p><small>${esc(new Date(a.time).toLocaleString('en-ZA'))}</small></div></div>`).join('')||'<p style="padding:15px 0;font-size:11px">No integration activity yet.</p>'}</div>`)}<div class="notice">Need your records from the original demo? ${button('Import browser records','onclick="importBrowserRecords()"')}</div>`}
function configure(id){const i=vault.find(x=>x.id===id)||{name:typeof id==='string'&&!id.includes('-')?id:'',mode:'direct',auth:'basic',endpoint:'',customer:''};showModal(`<h2>${i.id?'Edit integration':'Add integration'}</h2><form id="integration-form" autocomplete="off"><p style="font-size:11px">${i.id?'Leave credential fields blank to keep the saved values.':'Use a dedicated service account or API key for monitoring.'}</p>${field('Integration name','name',i.name)}<label for="f-connector">Connector</label><select id="f-connector" name="connector" required onchange="selectConnector()"><option value="" disabled ${!telemetryConnector(i)&&i.connector!=='mikrotik'?'selected':''}>Select a dedicated connector</option><option value="unifi-classic" ${i.connector==='unifi-classic'?'selected':''}>UniFi Classic Network</option><option value="pangolin" ${i.connector==='pangolin'?'selected':''}>Pangolin Network</option><option value="mikrotik-api" ${['mikrotik','mikrotik-api'].includes(i.connector)?'selected':''}>MikroTik Native API</option><option value="adguard" ${i.connector==='adguard'?'selected':''}>AdGuard Home</option><option value="pulse" ${i.connector==='pulse'?'selected':''}>Pulse · Proxmox PVE</option></select><p id="pulse-help" style="font-size:11px;margin-top:10px">Enter your Pulse server URL, for example http://pulse.internal:7655, optionally ending in /api. Create a Pulse API token with monitoring:read in API Access settings and enter it below. Do not use a Proxmox token. Reads PVE nodes, VMs, containers, storage and Pulse alert summaries every 60 seconds. Credentials remain on the backend.</p><p id="adguard-help" style="font-size:11px;margin-top:10px">Use the AdGuard Home web URL, optionally ending in /control. HTTP and HTTPS are supported. Use the web interface username/password. Polling reads status and aggregate statistics every 60 seconds. Query logs, domains and client identities are excluded.</p><div id="native-fields"><label for="f-native-transport">API transport</label><select id="f-native-transport" name="nativeTransport" onchange="selectNativeTransport()"><option value="tcp" ${!i.endpoint.startsWith('tls://')?'selected':''}>Plain TCP · api · 8728</option><option value="tls" ${i.endpoint.startsWith('tls://')?'selected':''}>TLS · api-ssl · 8729</option></select><p style="font-size:11px;margin:10px 0">Enter tcp://router:8728 or tls://router:8729. Use a local user with read and api policies. No www/www-ssl service is required. Credentials stay on the backend; plain TCP does not encrypt the connection. API-SSL requires a trusted certificate.</p></div><div id="pangolin-fields">${field('Pangolin Organization ID (optional for root keys)','orgId',i.orgId||'',false)}<p style="font-size:11px;margin:10px 0">Use the Integration API HTTPS host, optionally ending in /v1. Organization keys require an Organization ID. Grant List Sites and List Resources; List Site Resources includes private resources. A root key with List Organizations can discover organizations. <a class="text-link" href="https://docs.pangolin.net/self-host/advanced/integration-api" target="_blank" rel="noopener noreferrer">API setup ↗</a></p></div><p id="classic-help" style="font-size:11px;margin-top:10px">Classic uses a local-only account, a persistent backend cookie session and read-only endpoints. Enter the base URL; polling runs every 60 seconds, including while the dashboard is closed. Unattended polling runs on this server. Passwords and cookies never return from the server.</p><label for="f-mode">Connection route</label><select id="f-mode" name="mode" onchange="integrationFields()"><option value="direct" ${i.mode==='direct'?'selected':''}>Direct internal endpoint</option></select>${field('Service endpoint','endpoint',i.endpoint)}<label for="f-proxyAuth">Reverse-proxy authentication</label><select id="f-proxyAuth" name="proxyAuth" onchange="integrationFields()"><option value="none" ${!i.proxyAuth?'selected':''}>No additional proxy authentication</option><option value="pangolin" ${i.proxyAuth?'selected':''}>Pangolin resource access token</option></select><div id="proxy-fields">${secretField('Pangolin token ID','proxyId')}${secretField('Pangolin access token','proxyToken')}<p style="font-size:10px;margin-top:9px">Create a Shareable Link for this resource in Pangolin and use its Access Token Usage details. Uses P-Access-Token-Id and P-Access-Token headers; enter the service API key separately below. This token is different from Pangolin's management API key. <a class="text-link" href="https://docs.pangolin.net/manage/access-control/links" target="_blank" rel="noopener noreferrer">Setup guide ↗</a></p></div>${customerSelect(i.customer||'')}<label for="f-auth">Service authentication</label><select id="f-auth" name="auth" onchange="integrationFields()">${[['bearer','Bearer token'],['basic','Basic username / password']].map(([v,l])=>`<option value="${v}" ${i.auth===v?'selected':''}>${l}</option>`).join('')}</select><div id="token-fields">${secretField('API key / token','key')}</div><div id="basic-fields">${field('API username','username','',false)}${secretField('API password','password')}</div><p id="integration-error" class="red" role="alert" style="font-size:11px;margin-top:15px"></p><div class="form-actions">${button('Cancel','type="button" onclick="closeModal()"')}<button class="btn primary" id="integration-submit">Save securely</button></div></form>`);$('#f-endpoint').type='url';integrationFields();if(i.connector==='mikrotik')selectConnector();$('#classic-help').style.display=i.connector==='unifi-classic'?'block':'none';$('#integration-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let data=Object.fromEntries(f);if(['unifi-classic','pangolin','mikrotik-api','adguard','pulse'].includes(data.connector)){data.mode='direct';data.auth=['pangolin','pulse'].includes(data.connector)?'bearer':'basic'}data.credential={key:data.key,username:data.username,password:data.password,bridgeToken:data.bridgeToken,proxyId:data.proxyId,proxyToken:data.proxyToken};data.proxyAuth=data.proxyAuth==='pangolin';for(let k of ['key','username','password','bridgeToken','proxyId','proxyToken'])delete data[k];$('#integration-submit').disabled=true;$('#integration-error').textContent='';try{await api('integrations'+(i.id?'/'+i.id:''),i.id?'PATCH':'POST',data);e.target.reset();closeModal();await refreshVault();render();pollIntegrations();toast('Integration saved. Credentials stay on the server.')}catch(err){$('#integration-error').textContent=err.message;$('#integration-submit').disabled=false}}}
function secretField(label,name){return `<label for="f-${name}">${label}</label><input type="password" id="f-${name}" name="${name}" autocomplete="new-password" maxlength="8192" placeholder="${vault.length?'Blank keeps saved value when editing':'Enter credential'}">`}
function integrationFields(){if($('#f-connector')){const classic=$('#f-connector').value==='unifi-classic',pangolin=$('#f-connector').value==='pangolin',native=$('#f-connector').value==='mikrotik-api',adguard=$('#f-connector').value==='adguard',pulse=$('#f-connector').value==='pulse';$('#pulse-help').style.display=pulse?'block':'none';$('#adguard-help').style.display=adguard?'block':'none';$('#native-fields').style.display=native?'block':'none';$('#f-proxyAuth').disabled=native;if(native)$('#f-proxyAuth').value='none';$('#pangolin-fields').style.display=pangolin?'block':'none';$('#classic-help').style.display=classic?'block':'none';$('#f-mode').disabled=true;$('#f-auth').disabled=true;document.querySelector('label[for="f-username"]').textContent=classic?'Local UniFi username':adguard?'AdGuard Home username':native?'Local MikroTik username':'API username';document.querySelector('label[for="f-password"]').textContent=classic?'Local UniFi password':adguard?'AdGuard Home password':native?'Local MikroTik password':'API password';document.querySelector('label[for="f-endpoint"]').textContent=classic?'Controller base URL':pangolin?'Pangolin Integration API URL':native?'MikroTik API endpoint (tcp:// or tls://)':pulse?'Pulse server URL (HTTP/S)':adguard?'AdGuard Home web URL (HTTP/S)':'Service endpoint';if(classic||pangolin||native||adguard||pulse){$('#f-mode').value='direct';$('#f-auth').value=pangolin||pulse?'bearer':'basic'}}const selected=telemetryConnector({connector:$('#f-connector').value}),auth=$('#f-auth').value;$('#proxy-fields').style.display=$('#f-proxyAuth').value==='pangolin'?'block':'none';$('#token-fields').style.display=selected&&auth==='bearer'?'block':'none';$('#basic-fields').style.display=selected&&auth==='basic'?'block':'none'}
async function testIntegration(id,b){b.disabled=true;b.textContent='Testing…';try{const d=await api('integrations/'+id+'/test','POST',{});if(telemetryConnector(vault.find(i=>i.id===id)))classicData[id]=d;await refreshVault();render();toast(d.error||d.status+(d.latency?' · '+d.latency+' ms':''))}catch(e){b.disabled=false;b.textContent='Test connection';toast(e.message)}}
function deleteIntegration(id){const i=vault.find(x=>x.id===id);showModal(`<h2>Remove integration?</h2><p>The saved endpoint and encrypted credentials for ${esc(i.name)} will be deleted.</p><div class="form-actions">${button('Cancel','onclick="closeModal()"')}<button class="btn primary" id="delete-confirm">Remove</button></div>`);$('#delete-confirm').onclick=async()=>{try{await api('integrations/'+id,'DELETE',{});closeModal();await refreshVault();render();toast('Integration and credentials removed')}catch(e){toast(e.message)}}}
function downloadBridge(){showModal(`<h2>Private-service bridge</h2><p>Run this on a Linux VM or LXC on your LAN, then expose its /probe endpoint through Pangolin HTTPS. Set a strong bridge token and an explicit host:port allowlist. API credentials remain encrypted in Mission Control and are sent only to the bridge for each test.</p><p style="margin-top:15px">The setup guide and Docker files are included. No bridge is installed or connected automatically.</p><div class="form-actions">${button('Close','onclick="closeModal()"')}<a class="btn primary" href="/jdln-private-bridge.zip" download>Download bridge kit</a></div>`)}
function importBrowserRecords(){let old;try{old=JSON.parse(localStorage.getItem('jdln-mc-v1'))}catch{}if(!old)return toast('No original browser records found.');showModal(`<h2>Import browser records?</h2><p>This replaces your server-saved inventory, customer list, alerts and task board with records from the original demo in this browser. Integration credentials are unaffected.</p><div class="form-actions">${button('Cancel','onclick="closeModal()"')}<button class="btn primary" id="import-confirm">Import records</button></div>`);$('#import-confirm').onclick=async()=>{try{const data=Object.fromEntries(['customers','assets','alerts','tasks','activity'].map(k=>[k,old[k]||[]]));await api('workspace','PUT',data);state={...structuredClone(seed),...data,integrations:{}};closeModal();render();toast('Browser records imported')}catch(e){toast(e.message)}}}

function selectConnector(){if(['adguard','pulse'].includes($('#f-connector').value)){const el=$('#f-endpoint');try{if(el.value)el.value=new URL(el.value).origin}catch{}}if($('#f-connector').value==='mikrotik-api'){const el=$('#f-endpoint');if(!/^(tcp|tls):\/\//.test(el.value)){$('#f-native-transport').value='tcp';selectNativeTransport()}else $('#f-native-transport').value=el.value.startsWith('tls://')?'tls':'tcp'}const classic=$('#f-connector').value==='unifi-classic';if(classic){const el=$('#f-endpoint');try{el.value=el.value?new URL(el.value).origin:'https://controller.your-domain.com'}catch{el.value='https://controller.your-domain.com'}}integrationFields()}
async function loadClassicData(){const ids=new Set(vault.filter(i=>telemetryConnector(i)).map(i=>i.id));for(const id of Object.keys(classicData))if(!ids.has(id))delete classicData[id];for(const i of vault.filter(i=>telemetryConnector(i))){try{classicData[i.id]=await api('integrations/'+i.id+'/data')}catch(e){classicData[i.id]={...classicData[i.id],stale:true,error:e.message}}}}
function classicSummary(id){const d=classicData[id];return `<small class="${cacheStale(d)?'amber':'green'}">${cacheStale(d)?'Cached data stale':'Current snapshot'} · ${d?.lastSuccess?'Last successful update '+esc(new Date(d.lastSuccess).toLocaleString('en-ZA')):'No successful update yet'}</small>${d?.error?`<small class="red">${esc(d.error)}</small>`:''}`}
function viewClassic(id){classicOpened=classicOpened===id?null:id;render()}
function classicPanel(id,closable=true){const i=vault.find(i=>i.id===id),d=classicData[id];if(!i){classicOpened=null;return ''}if(i.connector==='pulse')return pulsePanel(i,d,closable);if(i.connector==='adguard')return adguardPanel(i,d,closable);if(i.connector==='mikrotik-api')return mikrotikPanel(i,d,closable);if(i.connector==='pangolin')return pangolinPanel(i,d,closable);return panel(esc(i.name)+' · Network data',`${classicSummary(id)}${d?.data?.sites?.map(site=>`<div style="padding:20px"><h2>${esc(site.desc||site.name)}</h2><p style="font-size:11px;margin:8px 0">Site identifier: ${esc(site.name)} · Connected clients: ${site.connectedClientCount}</p><div class="table-wrap"><table><thead><tr><th>DEVICE</th><th>MODEL</th><th>ADOPTION</th><th>STATE</th><th>UPTIME (S)</th><th>CLIENTS</th><th>VERSION</th></tr></thead><tbody>${site.devices.map(device=>`<tr><td>${esc(device.name||'Unnamed')}</td><td>${esc(device.model||'—')}</td><td>${esc(device.recordType)}</td><td>${esc(device.connectionState)}${device.state===null?'':' ('+device.state+')'}</td><td>${device.uptime??'—'}</td><td>${device.num_sta??'—'}</td><td>${esc(device.version||'—')}</td></tr>`).join('')||'<tr><td colspan="7">No device records.</td></tr>'}</tbody></table></div><div style="margin-top:15px">${site.health.map(h=>`<span class="tag neutral" style="margin:4px">${esc(h.subsystem||'Unknown subsystem')}: ${esc(h.status||'unknown')}</span>`).join('')}</div></div>`).join('')||'<div class="empty">Test the connection to load your first snapshot.</div>'}`,closable?`<button class="text-link" onclick="viewClassic('${id}')">Close</button>`:'')}
async function pollIntegrations(){if(!backendReady||pollRunning||workspaceMutation)return;pollRunning=true;try{await reloadDashboard();refreshLiveViews();await Promise.allSettled(vault.filter(telemetryConnector).map(async i=>{try{const d=await api('integrations/'+i.id+'/poll','POST',{});if(!vault.some(current=>current.id===i.id))return;if(telemetryConnector(i)){classicData[i.id]=d;i.status=d.error?'Polling failed':d.lastSuccess?'Connected':i.status;i.checkedAt=d.lastAttempt||i.checkedAt;i.latency=d.latency??i.latency}else{Object.assign(i,d);delete i.pollError}refreshLiveViews()}catch(e){if(!vault.some(current=>current.id===i.id))return;if(telemetryConnector(i))classicData[i.id]={...classicData[i.id],stale:true,error:e.message};else i.pollError=e.message;refreshLiveViews()}}));await reloadDashboard();refreshLiveViews()}catch(e){document.querySelector('footer span:nth-child(2)').textContent='Refresh failed · '+e.message;refreshLiveViews()}finally{pollRunning=false}}
async function reloadDashboard(){await syncChain;const epoch=workspaceEpoch;const [w,v,a]=await Promise.all([api('workspace'),api('integrations'),api('audit')]);if(epoch===workspaceEpoch&&!workspaceMutation&&!workspaceDirty&&w.data)state={...structuredClone(seed),...w.data,integrations:{}};const errors=Object.fromEntries(vault.filter(i=>i.pollError).map(i=>[i.id,i.pollError]));if(epoch===workspaceEpoch&&!workspaceMutation)vault=v.integrations.map(i=>({...i,...(errors[i.id]?{pollError:errors[i.id]}:{})}));auditEvents=a.events;await loadClassicData();document.querySelector('footer span:nth-child(2)').textContent='Auto refresh · '+new Date().toLocaleTimeString('en-ZA',{timeZone:'Africa/Johannesburg'})+' SAST · every 60s'}
setInterval(pollIntegrations,60000);
window.addEventListener('focus',()=>pollIntegrations());document.addEventListener?.('visibilitychange',()=>{if(document.visibilityState==='visible')pollIntegrations()});

function customerSelect(selected=''){const names=[...new Set(state.customers.map(c=>c.name))];if(selected&&!names.includes(selected))names.push(selected);return `<label for="f-customer">Customer</label><select id="f-customer" name="customer"><option value="" ${!selected?'selected':''}>Unassigned</option>${names.map(n=>`<option value="${esc(n)}" ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}</select>${state.customers.length?'':'<p>Add a customer in Customers to assign this integration.</p>'}`}
function integrationAssets(){return vault.flatMap(i=>{const d=classicData[i.id],sites=d?.data?.sites||[];if(i.connector==='pulse'&&d?.data?.resources)return pulseAssets(i,d);if(i.connector==='adguard'&&d?.data?.server)return adguardAssets(i,d);if(i.connector==='mikrotik-api'&&d?.data?.router)return mikrotikAssets(i,d);if(i.connector==='pangolin'&&d?.data?.organizations)return pangolinAssets(i,d);if(i.connector==='unifi-classic'&&sites.length)return sites.flatMap(site=>site.devices.map((a,n)=>({...a,name:a.name||'Unnamed device',type:a.recordType==='adopted'?'UniFi · '+(a.model||'Network device'):'UniFi · '+a.recordType,customer:i.customer||'Unassigned',site:site.desc||site.name,source:i.name,status:a.adopted===false?'Discovery / pending':a.connectionState==='connected'?'Connected':a.connectionState==='disconnected'?'Disconnected':a.connectionState==='pending/other'?'Pending / other':'Unknown',live:true,liveKey:i.id+':'+(a.assetId||site.name+':'+n),integrationId:i.id,lastSuccess:d.lastSuccess,stale:cacheStale(d)})));return [{name:i.name,type:i.connector==='pulse'?'Pulse monitor':i.connector==='adguard'?'AdGuard Home DNS':i.connector==='mikrotik-api'?'MikroTik router':i.connector==='pangolin'?'Pangolin API':i.connector==='unifi-classic'?'UniFi controller':'Removed connector',customer:i.customer||'Unassigned',address:i.target||i.endpoint,source:i.name,status:i.status||'Not tested',live:true,liveKey:i.id,integrationId:i.id,lastSuccess:telemetryConnector(i)?i.checkedAt:null,stale:telemetryConnector(i)?cacheStale(d):true}]})}
function inventory(){return [...integrationAssets(),...state.assets]}
function cacheStale(d){return !d||d.stale||d.data?.sourceStale||!d.lastSuccess||Date.now()-Date.parse(d.lastSuccess)>120000}
function customerIntegrations(name){return vault.filter(i=>i.customer===name).map(i=>`<div style="margin:14px 0"><strong>${esc(i.name)}</strong> ${tag(i.status)}${telemetryConnector(i)?classicSummary(i.id):removedConnectorNotice(i)}</div>`).join('')}
function operationAlerts(){const live=[];for(const i of vault){if(!telemetryConnector(i)){live.push({id:'integration-'+i.id,title:i.name+' · connector removed',source:i.customer||'Unassigned',severity:'warning',detail:'Select a dedicated connector or remove this integration. Polling is disabled.',live:true});continue}const d=classicData[i.id];if(i.connector==='pangolin'){if(cacheStale(d))live.push({id:'stale-'+i.id,title:i.name+' · telemetry stale',source:i.customer||'Unassigned',severity:'warning',detail:d?.error||'No current backend snapshot.',live:true});else for(const a of pangolinAssets(i,d))if(a.status==='Disconnected'||a.status==='Unhealthy')live.push({id:a.liveKey,title:a.name+' · '+a.status.toLowerCase(),source:a.customer,severity:'warning',detail:'Pangolin reported this state in the latest successful snapshot.',live:true});continue}if(cacheStale(d)){live.push({id:'stale-'+i.id,title:i.name+' · telemetry stale',source:i.customer||'Unassigned',severity:'warning',detail:d?.error||(d?.data?.sourceStale?'Pulse upstream monitoring data is stale or its update time is unavailable.':'No current backend snapshot. Device states below remain their last reported values.'),live:true});continue}if(i.connector==='pulse'){for(const a of d.data?.alerts||[])if(!a.acknowledged)live.push({id:'pulse-alert-'+i.id+'-'+(a.id||live.length),title:(a.resourceName||i.name)+' · '+(a.type||'Pulse alert'),source:i.customer||'Unassigned',severity:a.level==='critical'?'critical':'warning',detail:'Pulse reported this active alert. Review it in Pulse.',live:true});for(const r of d.data?.resources||[])if(['Disconnected','Critical','Warning','Stale'].includes(r.status))live.push({id:'pulse-resource-'+i.id+'-'+r.id,title:r.name+' · '+r.status.toLowerCase(),source:i.customer||'Unassigned',severity:r.status==='Critical'?'critical':'warning',detail:'Pulse reported this PVE resource state in its latest snapshot.',live:true});continue}if(i.connector==='adguard'){const s=d.data?.server;if(s?.running===false)live.push({id:'dns-stopped-'+i.id,title:i.name+' · DNS service stopped',source:i.customer||'Unassigned',severity:'warning',detail:'AdGuard Home reported its DNS service is not running in the latest successful snapshot.',live:true});if(s?.protectionEnabled===false)live.push({id:'dns-protection-'+i.id,title:i.name+' · protection disabled',source:i.customer||'Unassigned',severity:'warning',detail:'AdGuard Home reported protection is disabled in the latest successful snapshot.',live:true});continue}for(const site of d.data?.sites||[]){for(const device of site.devices)if(device.adopted===true&&device.state===0)live.push({id:'device-'+i.id+'-'+site.name+'-'+live.length,title:(device.name||device.model||'UniFi device')+' · disconnected',source:(i.customer||'Unassigned')+' · '+(site.desc||site.name),severity:'warning',detail:'The controller reported state 0 in the latest successful snapshot.',live:true});for(const h of site.health)if(h.status&&!['ok','healthy','good'].includes(h.status.toLowerCase()))live.push({id:'health-'+i.id+'-'+live.length,title:i.name+' · '+(h.subsystem||'Subsystem')+' health',source:(i.customer||'Unassigned')+' · '+(site.desc||site.name),severity:'warning',detail:'Controller status: '+h.status,live:true})}}return [...live,...state.alerts]}
function integrationPulse(){const devices=integrationAssets().filter(a=>a.type.startsWith('UniFi ·')),clients=Object.values(classicData).reduce((sum,d)=>sum+(d.data?.sites||[]).reduce((n,s)=>n+(s.connectedClientCount||0),0),0);return panel('Integration pulse',`<div class="health-strip"><span>Integrations <b>${vault.length}</b></span><span>UniFi devices <b>${devices.length}</b></span><span>Connected clients <b>${clients}</b></span><span>MikroTik routers <b>${vault.filter(i=>i.connector==='mikrotik-api').length}</b></span><span>PVE nodes <b>${integrationAssets().filter(a=>a.type==='Pulse · PVE node').length}</b></span><span>AdGuard servers <b>${vault.filter(i=>i.connector==='adguard').length}</b></span><span>Pangolin sites <b>${integrationAssets().filter(a=>a.type.startsWith('Pangolin site')).length}</b></span><span>Pangolin resources <b>${integrationAssets().filter(a=>a.type.startsWith('Pangolin resource')).length}</b></span></div><div style="padding:20px">${vault.map(i=>`<div style="margin-bottom:15px"><strong>${esc(i.name)}</strong> ${tag(i.status)}<small>${esc(i.customer||'Unassigned')}</small>${telemetryConnector(i)?classicSummary(i.id):removedConnectorNotice(i)}</div>`).join('')||'<p>No integrations configured. Add one in Integrations.</p>'}</div>`,button('Integrations ↗','onclick="go(\'integrations\')"'),'Backend polls every 60s in the background · cached counts on failure')}
function refreshLiveViews(){document.querySelector('.environment').innerHTML='<i></i> Secure workspace<span>'+vault.filter(i=>i.status==='Connected').length+' connected integrations · 60s refresh</span>';const view=location.hash.slice(1)||'overview';const keep={};for(const id of ['asset-search','asset-status','alert-filter','chat-input']){const el=$('#'+id);if(el)keep[id]=el.value}const focused=document.activeElement?.id,selection=document.activeElement?.selectionStart,selectionEnd=document.activeElement?.selectionEnd,scrollX=window.scrollX||0,scrollY=window.scrollY||0,chatScroll=$('#chat-log')?.scrollTop;render();for(const [id,value] of Object.entries(keep)){const el=$('#'+id);if(el)el.value=value}if(view==='infrastructure'&&$('#asset-search'))filterAssets();if(view==='alerts'&&$('#alert-filter'))renderAlerts();if(view==='agents'&&$('#chat-log')&&chatScroll!==undefined)$('#chat-log').scrollTop=chatScroll;if(focused){const el=$('#'+focused);el?.focus?.({preventScroll:true});if(typeof selection==='number')try{el?.setSelectionRange?.(selection,selectionEnd)}catch{}}window.scrollTo?.(scrollX,scrollY);if($('#modal').open&&detailModal){const d=detailModal;if(d.type==='customer'){const index=state.customers.findIndex(c=>c.name===d.name);if(index>=0)customerDetail(index);else closeModal()}else{const index=inventory().findIndex(a=>(a.liveKey||a.name)===d.key);if(index>=0)assetDetail(index);else closeModal()}}}

function removedConnectorNotice(i){return `<div class="notice">This connector was removed. Edit to select ${i.connector==='mikrotik'?'MikroTik Native API':'a dedicated connector'}, or remove this integration. Polling is disabled.</div>`}
function agentConnection(name){const i=vault.find(i=>i.name.toLowerCase().replace(/[^a-z]/g,'').includes(name.toLowerCase().replace(/[^a-z]/g,'')));return `<span id="connection-${name.replace(/[^a-z]/gi,'')}">${i?`${tag(i.status)}<small>API connectivity only</small>`:tag('Disconnected')}</span>`}
function customerStatus(c){const assets=integrationAssets().filter(a=>a.customer===c.name);if(!assets.length)return c.status;return assets.some(a=>a.stale||['Disconnected','Critical','Warning','Stale','Classic polling failed'].includes(a.status))?'Attention':'Healthy'}

function newCustomer(){customerForm()}
function editCustomer(index){customerForm(index)}
function customerForm(index){const c=state.customers[index];showModal(`<h2>${c?'Edit customer':'Add customer'}</h2><form id="customer-form">${field('Customer name','name',c?.name||'')}${field('Business / category','type',c?.type||'',false)}${field('Contact role or name','contact',c?.contact||'',false)}<p class="red" id="customer-error" role="alert"></p><div class="form-actions">${button('Cancel','type="button" onclick="closeModal()"')}<button class="btn primary" id="customer-submit">Save customer</button></div></form>`);$('#customer-form').onsubmit=async e=>{e.preventDefault();$('#customer-submit').disabled=true;try{const f=new FormData(e.target),data=Object.fromEntries(f);if(c)data.expectedName=c.name;await mutateCustomer(c?'customers/'+index:'customers',c?'PATCH':'POST',data);closeModal();refreshLiveViews();toast(c?'Customer updated · linked records updated':'Customer added')}catch(e){$('#customer-error').textContent=e.message;$('#customer-submit').disabled=false}}}
function deleteCustomer(index){const c=state.customers[index];if(!c)return;const assets=state.assets.filter(a=>a.customer===c.name).length,integrations=vault.filter(i=>i.customer===c.name).length;showModal(`<h2>Delete customer?</h2><p>Delete ${esc(c.name)} from your customer list?</p><p style="margin-top:15px">${assets} registered assets and ${integrations} integrations linked to this customer will be permanently deleted from Mission Control, including saved credentials and cached telemetry.</p><p class="red" id="customer-error" role="alert"></p><div class="form-actions">${button('Cancel','onclick="closeModal()"')}<button class="btn primary" id="customer-delete">Delete customer</button></div>`);$('#customer-delete').onclick=async()=>{$('#customer-delete').disabled=true;try{await mutateCustomer('customers/'+index,'DELETE',{expectedName:c.name});closeModal();refreshLiveViews();toast('Customer and linked assets, integrations and cached data deleted')}catch(e){$('#customer-error').textContent=e.message;$('#customer-delete').disabled=false}}}
async function mutateCustomer(path,method,data){workspaceMutation=true;workspaceEpoch++;try{await syncChain;if(workspaceDirty)throw Error('Your workspace has unsaved changes after a failed save. Retry saving or export them before changing customers.');const result=await api(path,method,data);state={...structuredClone(seed),...result.data,integrations:{}};vault=result.integrations;await refreshVault()}finally{workspaceMutation=false;workspaceEpoch++}}

function deleteAsset(index){const a=inventory()[index];if(!a)return;if(a.live){toast('Integration-managed assets can only be removed by deleting their integration.');return}const manualIndex=state.assets.indexOf(a),expected=structuredClone(a);showModal(`<h2>Delete asset?</h2><p>Remove ${esc(a.name)} from Mission Control?</p><p style="margin-top:15px">This manually registered inventory record will be permanently deleted.</p><p class="red" id="asset-delete-error" role="alert"></p><div class="form-actions">${button('Cancel','onclick="closeModal()"')}<button class="btn primary" id="asset-delete-confirm">Delete asset</button></div>`);$('#asset-delete-confirm').onclick=async()=>{$('#asset-delete-confirm').disabled=true;try{await mutateCustomer('assets/'+manualIndex,'DELETE',{expected});closeModal();refreshLiveViews();toast('Manual asset deleted')}catch(e){$('#asset-delete-error').textContent=e.message;$('#asset-delete-confirm').disabled=false}}}

function telemetryConnector(i){return ['unifi-classic','pangolin','mikrotik-api','adguard','pulse'].includes(i?.connector)}
function adguardAssets(i,d){const s=d?.data?.server;if(!s)return [];return [{name:i.name,type:'AdGuard Home DNS',model:'AdGuard Home',version:s.version,address:i.endpoint,status:s.running===false?'Stopped':s.protectionEnabled===false?'Protection disabled':s.running===true?'Connected':'Unknown',dnsRunning:s.running,protectionEnabled:s.protectionEnabled,customer:i.customer||'Unassigned',source:i.name,live:true,liveKey:i.id+':dns',integrationId:i.id,lastSuccess:d.lastSuccess,stale:cacheStale(d)}]}
function adguardPanel(i,d,closable){const s=d?.data?.server,t=d?.data?.stats;return panel(esc(i.name)+' · AdGuard Home data',classicSummary(i.id)+(s?`<div style="padding:20px"><h2>${esc(i.name)}</h2><p style="font-size:11px;margin:10px 0">AdGuard Home ${esc(s.version)} · DNS service: ${s.running===true?'Running':s.running===false?'Stopped':'Unknown'} · Protection: ${s.protectionEnabled?'Enabled':'Disabled'}</p><div class="health-strip"><span>Queries <b>${t.queries??'—'}</b></span><span>Blocked by filters <b>${t.blockedByFiltering??'—'}</b></span><span>Filtering rate <b>${t.filteringPercent===null?'—':t.filteringPercent+'%'}</b></span><span>Average processing <b>${t.averageProcessingMs===null?'—':t.averageProcessingMs+' ms'}</b></span></div><p style="font-size:11px;margin:12px 0">Totals cover AdGuard's configured statistics reporting window; they are not counts for the latest poll.</p><div class="table-wrap"><table><tbody>${[['DNS port',s.dnsPort],['Web port',s.httpPort],['Web API started',s.startedAt?new Date(s.startedAt).toLocaleString('en-ZA'):null],['Safe browsing blocked',t.blockedBySafeBrowsing],['Parental filtering blocked',t.blockedByParental],['Safe search replacements',t.safeSearchReplacements]].map(([label,value])=>`<tr><td>${esc(label)}</td><td>${esc(value??'—')}</td></tr>`).join('')}</tbody></table></div></div>`:'<div class="empty">Test connection to load AdGuard Home status and statistics.</div>'),closable?`<button class="text-link" onclick="viewClassic('${i.id}')">Close</button>`:'')}
function selectNativeTransport(){const el=$('#f-endpoint'),transport=$('#f-native-transport').value;try{const u=new URL(el.value),custom=['tcp:','tls:'].includes(u.protocol)&&u.port&&!['8728','8729'].includes(u.port);el.value=transport+'://'+u.hostname+':'+(custom?u.port:transport==='tls'?'8729':'8728')}catch{el.value=transport+'://router.internal:'+(transport==='tls'?'8729':'8728')}integrationFields()}
function mikrotikAssets(i,d){const r=d?.data?.router;if(!r)return [];return [{name:r.name||i.name,type:'MikroTik router',model:r.model,version:r.version,uptime:r.uptime,cpu:r.cpuLoad,ram:r.memoryUsage,status:'Connected',address:i.endpoint,customer:i.customer||'Unassigned',source:i.name,live:true,liveKey:i.id+':router',integrationId:i.id,lastSuccess:d.lastSuccess,stale:cacheStale(d)}]}
function mikrotikPanel(i,d,closable){const r=d?.data?.router;return panel(esc(i.name)+' · MikroTik data',classicSummary(i.id)+(r?`<div style="padding:20px"><h2>${esc(r.name)}</h2><p style="font-size:11px;margin:10px 0">${esc(r.model||'MikroTik')} · RouterOS ${esc(r.version||'—')} · Uptime ${esc(r.uptime||'—')}</p><div class="health-strip"><span>CPU <b>${r.cpuLoad??'—'}${r.cpuLoad===null?'':'%'}</b></span><span>Memory <b>${r.memoryUsage??'—'}${r.memoryUsage===null?'':'%'}</b></span><span>Interfaces <b>${d.data.interfaces.length}</b></span></div><p style="font-size:11px;margin:12px 0">Interface counters are cumulative bytes. Non-running interfaces may be unused or disconnected.</p><div class="table-wrap"><table><thead><tr><th>INTERFACE</th><th>TYPE</th><th>STATE</th><th>MTU</th><th>RX BYTES</th><th>TX BYTES</th></tr></thead><tbody>${d.data.interfaces.map(a=>`<tr><td>${esc(a.name||'Unnamed')}</td><td>${esc(a.type||'—')}</td><td>${esc(a.disabled===true?'Disabled':a.running===true?'Running':a.running===false?'Not running':'Unknown')}</td><td>${a.mtu??'—'}</td><td>${a.rxBytes??'—'}</td><td>${a.txBytes??'—'}</td></tr>`).join('')||'<tr><td colspan="6">No interfaces returned.</td></tr>'}</tbody></table></div></div>`:'<div class="empty">Test connection to load MikroTik telemetry.</div>'),closable?`<button class="text-link" onclick="viewClassic('${i.id}')">Close</button>`:'')}
function pangolinAssets(i,d){return (d?.data?.organizations||[]).flatMap(org=>[...org.sites.map(a=>({name:a.name||'Unnamed site',type:'Pangolin site · '+(a.type||'unknown'),status:a.online===true?'Connected':a.online===false?'Disconnected':a.type==='local'?'Local / unmonitored':'Unknown',address:'—',version:a.version,liveKey:i.id+':'+org.orgId+':site:'+a.siteId})),...[...org.resources,...org.privateResources].map(a=>({name:a.name||'Unnamed resource',type:'Pangolin resource · '+a.kind,status:a.enabled===false?'Disabled':a.health==='unhealthy'?'Unhealthy':a.health==='healthy'?'Healthy':a.enabled===true?'Enabled / unmonitored':'Unknown',address:a.domain||'—',liveKey:i.id+':'+org.orgId+':'+a.kind+':'+a.resourceId}))].map(a=>({...a,customer:i.customer||'Unassigned',site:org.name,source:i.name,live:true,integrationId:i.id,lastSuccess:d.lastSuccess,stale:cacheStale(d)})))}
function pangolinPanel(i,d,closable){return panel(esc(i.name)+' · Pangolin data',classicSummary(i.id)+(d?.data?.warnings||[]).map(w=>`<div class="notice">${esc(w)}</div>`).join('')+(d?.data?.organizations||[]).map(org=>`<div style="padding:20px"><h2>${esc(org.name)}</h2><p style="font-size:11px;margin:10px 0">${org.sites.length} sites · ${org.resources.length} public resources · ${org.privateResources.length} private resources. Enabled resources are configuration state; health appears only when Pangolin reports it.</p>${assetsTable(pangolinAssets(i,{...d,data:{organizations:[org]}}),true)}</div>`).join('')+(!d?.data?'<div class="empty">Test connection to load Pangolin data. Check the API URL, Organization ID and key read permissions if it fails.</div>':''),closable?`<button class="text-link" onclick="viewClassic('${i.id}')">Close</button>`:'')}

function migrationDialog(){showModal('<h2>Import hosted workspace</h2><p>Select the JSON from Export report in the hosted dashboard. This imports customers, manual assets, alerts, tasks and activity into an empty workspace. Integration settings are imported without credentials; re-enter those locally.</p><input id="migration-file" type="file" accept="application/json"><p id="migration-error" class="red"></p><div class="form-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" id="migration-import">Import</button></div>');$('#migration-import').onclick=async()=>{try{const file=$('#migration-file').files[0];if(!file)throw Error('Select a report first.');await api('migration/import','POST',JSON.parse(await file.text()));closeModal();await bootBackend();toast('Workspace imported. Re-enter integration credentials locally.')}catch(e){$('#migration-error').textContent=e.message}}}

function pulseAssets(i,d){return (d?.data?.resources||[]).map(r=>({...r,type:'Pulse · '+({node:'PVE node',vm:'Virtual machine',container:'LXC container',storage:'PVE storage'}[r.kind]||r.kind),model:r.vmid!==null?'VMID '+r.vmid:r.version||'Proxmox PVE',site:r.node||r.instance,customer:i.customer||'Unassigned',source:i.name,live:true,liveKey:i.id+':'+r.kind+':'+r.id,integrationId:i.id,lastSuccess:d.lastSuccess,stale:cacheStale(d)||r.status==='Stale'}))}
function pulsePanel(i,d,closable){const data=d?.data,s=data?.summary;const metric=value=>value===null||value===undefined?'—':esc(value)+'%';return panel(esc(i.name)+' · Pulse / Proxmox PVE',classicSummary(i.id)+(data?`<div style="padding:20px"><p style="font-size:11px;margin-bottom:12px">Pulse monitoring updated: ${data.sourceUpdatedAt?esc(new Date(data.sourceUpdatedAt).toLocaleString('en-ZA')):'Unknown'} · ${data.sourceStale?'Upstream data stale':'Upstream snapshot current'}</p><div class="health-strip">${[['PVE nodes',s.nodes],['VMs',s.vms],['LXC containers',s.containers],['Storage',s.storage],['Pulse active alerts',s.activeAlerts??'Unknown']].map(([label,count])=>`<span>${label} <b>${count}</b></span>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>RESOURCE</th><th>TYPE / NODE</th><th>STATE</th><th>CPU</th><th>MEMORY</th><th>DISK</th><th>UPTIME (S)</th></tr></thead><tbody>${data.resources.map(r=>`<tr><td>${esc(r.name)}${r.vmid!==null?'<small>VMID '+r.vmid+'</small>':''}</td><td>${esc(r.kind)}<small>${esc(r.node||r.instance||'—')}</small></td><td>${tag(r.status)}</td><td>${metric(r.cpuPercent)}</td><td>${metric(r.memory.percent)}</td><td>${metric(r.disk.percent)}</td><td>${esc(r.uptime??'—')}</td></tr>`).join('')||'<tr><td colspan="7">No PVE resources returned by Pulse.</td></tr>'}</tbody></table></div><p style="font-size:11px;margin-top:12px">Powered-off workloads remain stopped. Pulse alert counts cover all systems monitored by this Pulse server.${s.alertsTruncated?' Showing the first 200 alert summaries.':''}</p>${data.alerts.map(a=>`<p style="font-size:11px;margin-top:8px">${esc(a.resourceName||'Pulse')} · ${esc(a.type||'Alert')} · ${esc(a.level)}${a.acknowledged?' · Acknowledged in Pulse':''}</p>`).join('')}</div>`:'<div class="empty">Test connection to load Pulse PVE inventory and health.</div>'),closable?`<button class="text-link" onclick="viewClassic('${i.id}')">Close</button>`:'')}
